create function public.verse_range_summary(_from integer,_to integer) returns table(jumlah_baris integer,halaman_dari integer,halaman_sampai integer) language sql stable security invoker set search_path=public as $$select (b.halaman-a.halaman)*15+b.baris_akhir-a.baris_awal+1,a.halaman,b.halaman from public.quran_ayat a join public.quran_ayat b on b.id=_to where a.id=_from and _to>=_from and auth.uid() is not null$$;
revoke all on function public.verse_range_summary(integer,integer) from public,anon;grant execute on function public.verse_range_summary(integer,integer) to authenticated;
create function public.set_user_role(_user uuid,_role public.app_role) returns void language plpgsql security definer set search_path=public as $$begin if not public.has_role(auth.uid(),'admin') then raise exception 'Akses admin diperlukan';end if;if _user=auth.uid() and _role<>'admin' then raise exception 'Admin tidak dapat menurunkan peran sendiri';end if;delete from public.user_roles where user_id=_user;insert into public.user_roles(user_id,role) values(_user,_role);end$$;
revoke all on function public.set_user_role(uuid,public.app_role) from public,anon;grant execute on function public.set_user_role(uuid,public.app_role) to authenticated;